"""Decode SourceGuardian ``sg_load`` containers without a PHP runtime.

Pipeline: base64 payload -> 12-byte machine prefix -> preheader TLV ->
Blowfish-CBC (IV = 0) -> ROL1 checksum gate -> LZO1X -> SOURCEGUARDIAN body.

The body area is a list, not one section: each entry is
``[u32 id][u32 padded length][encrypted section]`` and the list ends at a zero
marker.  Files that carry a bare section with no marker still decode through
the single-section fallback.

Keys come from ``sg_keys.py`` (generated by sg_key_extractor.py).  Three
commercial keys are tried first, then the 253 evaluation-mode candidates
derived as ``KEY1[:16] + bytes([name_len])``.

Usage:
    python sg_container_decode.py encoded.php --out dump/
    python sg_container_decode.py encoded.php --keys-only

The LZO1X match encodings follow minilzo (M2/M3/M4, ``+0x4000`` only for M4);
the published write-up merges the branches and adds the offset to all three,
which mis-decodes any match.  The literal run path is covered by tests; the
match path is only exercised once a real encoded fixture is available.
"""

from __future__ import annotations

import argparse
import base64
import re
import struct
import sys
from pathlib import Path

M32 = 0xFFFFFFFF
MAGIC = b"SOURCEGUARDIAN\x00"
MAX_DECLEN = 200_000_000
_CALL_RE = re.compile(r"sg_load\s*\(\s*(['\"])([A-Za-z0-9+/=\s]+?)\1\s*\)")

# First 1042 32-bit words of the fractional hexadecimal expansion of pi:
# P-array (18 words) followed by S-boxes S1..S4 (4 x 256 words).
_PI_HEX_CHUNKS: tuple[str, ...] = (
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "77AFA1C52075606085CBFE4E8AE88DD87AAAF9B04CF9AA7E1948C25C02FB8A8C01C36AE4D6EBE1F990D4F869A65CDEA03F09252DC208E69FB74E6132CE77E25B578FDFE33AC372E6",
)


class SGError(Exception):
    """Malformed container, wrong key, or unsupported layout."""


def _pi_words() -> list[int]:
    hexstr = "".join(_PI_HEX_CHUNKS)
    if len(hexstr) != 8336:
        raise SGError(f"pi constant table is {len(hexstr)} hex digits, expected 8336")
    return [int(hexstr[i:i + 8], 16) for i in range(0, 8336, 8)]


_PI_WORDS = _pi_words()


class Blowfish:
    """Standard Blowfish with the pi-derived P-array and S-boxes."""

    __slots__ = ("p", "s")

    def __init__(self, key: bytes) -> None:
        if not key:
            raise SGError("empty Blowfish key")
        words = _PI_WORDS
        p = list(words[:18])
        s = list(words[18:])
        index = 0
        for slot in range(18):
            word = 0
            for _ in range(4):
                word = (word << 8) | key[index]
                index = (index + 1) % len(key)
            p[slot] ^= word
        self.p, self.s = p, s
        left = right = 0
        for slot in range(0, 18, 2):
            left, right = self.encrypt_block(left, right)
            self.p[slot], self.p[slot + 1] = left, right
        for slot in range(0, 1024, 2):
            left, right = self.encrypt_block(left, right)
            self.s[slot], self.s[slot + 1] = left, right

    def _f(self, value: int) -> int:
        s = self.s
        mixed = (s[value >> 24] + s[256 + ((value >> 16) & 0xFF)]) & M32
        mixed ^= s[512 + ((value >> 8) & 0xFF)]
        return (mixed + s[768 + (value & 0xFF)]) & M32

    def encrypt_block(self, left: int, right: int) -> tuple[int, int]:
        p = self.p
        for round_index in range(16):
            left ^= p[round_index]
            right ^= self._f(left)
            left, right = right, left
        left, right = right, left
        right ^= p[16]
        left ^= p[17]
        return left & M32, right & M32

    def decrypt_block(self, left: int, right: int) -> tuple[int, int]:
        p = self.p
        for round_index in range(17, 1, -1):
            left ^= p[round_index]
            right ^= self._f(left)
            left, right = right, left
        left, right = right, left
        right ^= p[1]
        left ^= p[0]
        return left & M32, right & M32


def cbc_decrypt(cipher: Blowfish, data: bytes) -> bytes:
    """Blowfish-CBC with a zero IV; trailing bytes that do not fill a block drop."""
    out = bytearray()
    prev_left = prev_right = 0
    for offset in range(0, len(data) - 7, 8):
        cipher_left = int.from_bytes(data[offset:offset + 4], "big")
        cipher_right = int.from_bytes(data[offset + 4:offset + 8], "big")
        left, right = cipher.decrypt_block(cipher_left, cipher_right)
        out += struct.pack(">II", left ^ prev_left, right ^ prev_right)
        prev_left, prev_right = cipher_left, cipher_right
    return bytes(out)


def rol1(data: bytes) -> int:
    value = 0
    for byte in data:
        value = (value + byte) & M32
        value = ((value << 1) | (value >> 31)) & M32
    return value


def get_payload(path: Path) -> bytes:
    """Return the container bytes: last sg_load() argument minus the 12-byte prefix."""
    text = path.read_text(encoding="latin-1")
    matches = list(_CALL_RE.finditer(text))
    if not matches:
        raise SGError("no sg_load('...') argument found")
    encoded = re.sub(r"\s+", "", matches[-1].group(2))
    try:
        blob = base64.b64decode(encoded, validate=True)
    except ValueError as exc:
        raise SGError(f"sg_load argument is not valid base64: {exc}") from exc
    if len(blob) <= 12:
        raise SGError(f"payload is only {len(blob)} bytes")
    return blob[12:]


def parse_preheader(buf: bytes) -> tuple[int, int, int | None, int]:
    """Walk the plaintext TLV; returns (version, metadata size, flags, body offset)."""
    pos = 0
    version = 0
    metadata_size: int | None = None
    flags: int | None = None
    while True:
        if pos >= len(buf):
            raise SGError("preheader runs past end of container")
        tag = buf[pos]
        pos += 1
        if tag == 0xFF:
            break
        if pos + 4 > len(buf):
            raise SGError("preheader field truncated")
        if tag == 0x00:
            if pos + 8 > len(buf):
                raise SGError("preheader version field truncated")
            version = int.from_bytes(buf[pos + 4:pos + 8], "little")
            pos += 8
        elif tag == 0x04:
            metadata_size = int.from_bytes(buf[pos:pos + 4], "little")
            pos += 4
        else:
            skip = int.from_bytes(buf[pos:pos + 4], "little")
            pos += 4
            if pos + skip > len(buf):
                raise SGError("preheader skip field runs past end of container")
            if tag == 0x80 and skip == 4:
                flags = int.from_bytes(buf[pos:pos + 4], "little")
            pos += skip
    if metadata_size is None:
        raise SGError("preheader has no metadata size (tag 0x04)")
    return version, metadata_size, flags, pos


def _section_header(plain: bytes) -> tuple[int, int, int] | None:
    if len(plain) < 12:
        return None
    checksum, length, declen = struct.unpack_from("<III", plain, 0)
    if checksum == 0 or length < 12 or length > len(plain):
        return None
    if declen > MAX_DECLEN:
        return None
    return checksum, length, declen


def decrypt_section(key: bytes, buf: bytes, offset: int) -> tuple[int, int, bytes] | None:
    """Decrypt one section with one key; None when the ROL1 gate rejects it."""
    available = len(buf) - offset
    if available < 16:
        return None
    cipher = Blowfish(key)
    peek = cbc_decrypt(cipher, buf[offset:offset + 8])
    length = int.from_bytes(peek[4:8], "little")
    if length < 12 or length > available:
        return None
    blocks = min(available, ((length + 7) // 8) * 8)
    plain = cbc_decrypt(cipher, buf[offset:offset + blocks])[:length]
    header = _section_header(plain)
    if header is None:
        return None
    checksum, length, declen = header
    if rol1(b"\x00\x00\x00\x00" + plain[4:length]) != checksum:
        return None
    return length, declen, plain


def inflate(plain: bytes, length: int, declen: int) -> bytes:
    payload = plain[12:length - 3]
    if declen == 0:
        return payload
    out = lzo1x_decompress(payload)
    if len(out) != declen:
        raise SGError(f"section declares {declen} bytes but inflated to {len(out)}")
    return out


def lzo1x_decompress(src: bytes) -> bytes:
    out = bytearray()
    ip = 0
    size = len(src)

    def take(count: int) -> None:
        nonlocal ip
        if count < 0 or ip + count > size:
            raise SGError(f"LZO1X literal run of {count} bytes overruns input")
        out.extend(src[ip:ip + count])
        ip += count

    def copy_match(distance: int, count: int) -> None:
        if distance < 1 or distance > len(out):
            raise SGError(f"LZO1X match distance {distance} exceeds output {len(out)}")
        start = len(out) - distance
        for step in range(count):
            out.append(out[start + step])

    def extended_length(base: int, mask: int) -> int:
        nonlocal ip
        count = base
        while True:
            if ip >= size:
                raise SGError("LZO1X length run overruns input")
            byte = src[ip]
            ip += 1
            if byte:
                break
            count += 255
        return count + mask + byte

    if size == 0:
        raise SGError("empty LZO1X stream")

    t = src[ip]
    ip += 1
    if t > 17:
        t -= 17
        take(t)
        state = "flr" if t >= 4 else "match"
    else:
        ip -= 1
        state = "top"

    while True:
        if state == "top":
            if ip >= size:
                raise SGError("LZO1X stream ended without EOF marker")
            t = src[ip]
            ip += 1
            if t >= 16:
                state = "match"
                continue
            if t == 0:
                t = extended_length(0, 15)
            take(t + 3)
            state = "flr"
        elif state == "flr":
            if ip >= size:
                raise SGError("LZO1X stream ended before short match")
            t = src[ip]
            ip += 1
            if t >= 16:
                state = "match"
                continue
            if ip + 1 > size:
                raise SGError("LZO1X short match truncated")
            distance = 1 + 0x0800 + (t >> 2) + (src[ip] << 2)
            ip += 1
            copy_match(distance, 3)
            state = "mdone"
        elif state == "match":
            if t >= 64:
                if ip + 1 > size:
                    raise SGError("LZO1X M2 match truncated")
                distance = 1 + ((t >> 2) & 7) + (src[ip] << 3)
                ip += 1
                count = (t >> 5) + 1
            elif t >= 32:
                count = t & 31
                if count == 0:
                    count = extended_length(0, 31)
                count += 2
                if ip + 2 > size:
                    raise SGError("LZO1X M3 match truncated")
                distance = 1 + (src[ip] >> 2) + (src[ip + 1] << 6)
                ip += 2
            elif t >= 16:
                distance = (t & 8) << 11
                count = t & 7
                if count == 0:
                    count = extended_length(0, 7)
                count += 2
                if ip + 2 > size:
                    raise SGError("LZO1X M4 match truncated")
                distance += (src[ip] >> 2) + (src[ip + 1] << 6)
                ip += 2
                if distance == 0:
                    break
                distance += 0x4000
            else:
                if t == 0:
                    t = extended_length(0, 15)
                take(t + 3)
                state = "flr"
                continue
            copy_match(distance, count)
            state = "mdone"
        elif state == "mdone":
            trailing = src[ip - 2] & 3
            if trailing == 0:
                state = "top"
            else:
                take(trailing)
                if ip >= size:
                    raise SGError("LZO1X stream ended after trailing literals")
                t = src[ip]
                ip += 1
                state = "match"
        else:  # pragma: no cover - unreachable
            raise SGError(f"bad LZO1X state {state}")

    return bytes(out)


def build_candidates(keys: tuple[bytes, ...] | list[bytes]) -> list[tuple[str, bytes]]:
    candidates = [(f"commercial-key{index}", key) for index, key in enumerate(keys)]
    if keys:
        prefix = keys[1][:16] if len(keys) > 1 else keys[0][:16]
        candidates += [(f"eval-0x{value:02x}", prefix + bytes([value])) for value in range(3, 256)]
    return candidates


def load_keys() -> tuple[bytes, ...]:
    try:
        from . import keys as sg_keys
    except ImportError:
        try:
            import sg_keys
        except ImportError as exc:
            raise SGError(
                "keys.py / sg_keys.py not found; run: python tools/sg_key_extractor.py loader/*.win"
            ) from exc
    keys = tuple(getattr(sg_keys, "SG_KEYS", ()))
    if not keys:
        raise SGError("keys.py exports no SG_KEYS")
    return keys


def decode_bytes(buf: bytes, keys: tuple[bytes, ...]) -> dict:
    """Decrypt metadata, locate the body with the same key, inflate both."""
    version, metadata_size, flags, metadata_offset = parse_preheader(buf)
    if metadata_size < 12 or metadata_offset + metadata_size > len(buf):
        raise SGError(
            f"metadata section of {metadata_size} bytes does not fit in {len(buf)}"
        )

    for name, key in build_candidates(keys):
        found = decrypt_section(key, buf, metadata_offset)
        if found is None:
            continue
        length, declen, plain = found
        metadata = inflate(plain, length, declen)
        bodies = _collect_bodies(key, buf, metadata_offset + metadata_size)
        return {
            "key": name,
            "version": version,
            "flags": flags,
            "metadata": metadata,
            "bodies": bodies,
            "metadata_size": length,
            "body_size": sum(len(body) for body in bodies),
        }

    raise SGError(
        "no key candidate opened the metadata section; "
        "check that sg_keys.py came from the loader build that encoded this file"
    )


def _collect_bodies(key: bytes, buf: bytes, offset: int) -> list[bytes]:
    """Walk the body list: [u32 id][u32 padded length][section] ... 0."""
    bodies: list[bytes] = []
    pos = offset
    while pos + 8 <= len(buf):
        marker, span = struct.unpack_from("<II", buf, pos)
        if marker == 0:
            break
        if span >= 12 and span % 8 == 0 and pos + 8 + span <= len(buf):
            found = decrypt_section(key, buf, pos + 8)
            if found is not None:
                length, declen, plain = found
                bodies.append(inflate(plain, length, declen))
                pos += 8 + span
                continue
        if not bodies:
            found = decrypt_section(key, buf, pos)
            if found is None:
                raise SGError(f"body section at offset {pos} failed the ROL1 gate")
            length, declen, plain = found
            bodies.append(inflate(plain, length, declen))
            return bodies
        break
    if not bodies:
        raise SGError("no body section found after the metadata section")
    return bodies


def _meta_u32(meta: bytes, pos: int) -> int:
    if pos + 4 > len(meta):
        raise SGError("metadata field truncated")
    return int.from_bytes(meta[pos:pos + 4], "little")


def _read_metadata_record(meta: bytes, pos: int) -> tuple[list[dict], int]:
    fields: list[dict] = []
    while pos < len(meta):
        tag = meta[pos]
        pos += 1
        if tag == 0xFF:
            return fields, pos
        if tag == 0x0A:
            fields.append({"tag": tag, "kind": "fixed4", "value": _meta_u32(meta, pos)})
            pos += 4
        elif tag == 0x01:
            if pos >= len(meta):
                raise SGError("metadata flag field truncated")
            fields.append({"tag": tag, "kind": "fixed1", "value": meta[pos]})
            pos += 1
        elif tag in (0x0D, 0x0E):
            count = _meta_u32(meta, pos)
            pos += 4
            items = []
            for _ in range(count):
                size = _meta_u32(meta, pos)
                pos += 4
                if pos + size > len(meta):
                    raise SGError("metadata list item runs past end of record")
                items.append(meta[pos:pos + size])
                pos += size
            fields.append({"tag": tag, "kind": "list", "items": items})
        else:
            size = _meta_u32(meta, pos)
            pos += 4
            if pos + size > len(meta):
                raise SGError("metadata value runs past end of record")
            fields.append({"tag": tag, "kind": "bytes", "value": meta[pos:pos + size]})
            pos += size
    raise SGError("metadata record ended without a 0xff terminator")


def parse_metadata(meta: bytes) -> dict:
    """Decode the metadata block: one 0x02 machine record plus policy records.

    Most fields are u32-length-prefixed.  Tags 0x0a and 0x01 are bare values
    (4 and 1 bytes) and 0x0d/0x0e are counted lists, so a walker that assumes
    every tag is length-prefixed desynchronises right after the 0x04 field.
    """
    if not meta or meta[0] != 0x02:
        raise SGError("metadata does not start with tag 0x02")
    regkey_length = _meta_u32(meta, 1)
    regkey_end = 5 + regkey_length
    if regkey_length < 2 or regkey_end > len(meta):
        raise SGError("metadata machine record is truncated")
    records = []
    pos = regkey_end
    while pos < len(meta):
        fields, pos = _read_metadata_record(meta, pos)
        records.append(fields)
    return {
        "regkey": meta[5:regkey_end - 1].decode("ascii", "replace"),
        "records": records,
        "size": len(meta),
    }


def describe_body(body: bytes) -> tuple[int, int]:
    if not body.startswith(MAGIC):
        raise SGError(f"body does not start with {MAGIC!r}: {body[:16]!r}")
    if len(body) < 23:
        raise SGError("body header truncated")
    version, flags = struct.unpack_from("<II", body, len(MAGIC))
    return version, flags


def decode_file(
    path: Path | str,
    keys: tuple[bytes, ...] | None = None,
    out_dir: Path | None = None,
) -> dict:
    if keys is None:
        keys = load_keys()
    path = Path(path)
    result = decode_bytes(get_payload(path), keys)
    result["containers"] = [describe_body(body) for body in result["bodies"]]
    if result["bodies"]:
        result["body"] = result["bodies"][0]
    if out_dir is not None:
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / f"{path.stem}.meta.bin").write_bytes(result["metadata"])
        bodies = result["bodies"]
        if len(bodies) == 1:
            targets = [out_dir / f"{path.stem}.body.bin"]
        else:
            targets = [out_dir / f"{path.stem}.body.{index}.bin" for index in range(len(bodies))]
        for target, body in zip(targets, bodies):
            target.write_bytes(body)
        result["body_paths"] = targets
    return result


def _format_metadata_field(field: dict) -> str:
    kind = field["kind"]
    if kind == "bytes":
        return f"0x{field['tag']:02x} bytes[{len(field['value'])}] {field['value']!r}"
    if kind == "list":
        joined = ", ".join(repr(item) for item in field["items"])
        return f"0x{field['tag']:02x} list[{len(field['items'])}] {joined}"
    return f"0x{field['tag']:02x} {kind} {field['value']}"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Decode SourceGuardian sg_load containers statically.",
    )
    parser.add_argument("input", type=Path, help="Encoded PHP file")
    parser.add_argument("-o", "--out", type=Path, default=Path("dump"), help="Output directory")
    parser.add_argument(
        "--keys-only",
        action="store_true",
        help="Print loaded key fingerprints and exit",
    )
    parser.add_argument(
        "--metadata",
        action="store_true",
        help="Print the parsed metadata TLV records",
    )
    args = parser.parse_args(argv)

    try:
        keys = load_keys()
    except SGError as exc:
        print(f"[-] {exc}", file=sys.stderr)
        return 2

    if args.keys_only:
        import hashlib

        print(f"[*] {len(keys)} commercial key(s) loaded")
        for index, key in enumerate(keys):
            print(f"    KEY{index}: sha256[:8]={hashlib.sha256(key).hexdigest()[:8]} length={len(key)}")
        return 0

    if not args.input.is_file():
        print(f"[-] not found: {args.input}", file=sys.stderr)
        return 2

    try:
        result = decode_file(args.input, keys, args.out)
    except SGError as exc:
        print(f"[-] {exc}", file=sys.stderr)
        return 1

    flags = result["flags"]
    versions = {(ver, fl) for ver, fl in result["containers"]}
    print(
        f"[{args.input.name}] key={result['key']} "
        f"preheader(ver={result['version']} meta={result['metadata_size']}) "
        f"meta={len(result['metadata'])}B sections={len(result['bodies'])} "
        f"body={result['body_size']}B "
        f"flags={'-' if flags is None else hex(flags)}"
    )
    print(
        "    containers: "
        + ", ".join(f"ver={hex(ver)} flags={hex(fl)}" for ver, fl in sorted(versions))
        + " magic=OK"
    )
    print(f"    wrote {args.out / (args.input.stem + '.meta.bin')}")
    for target in result["body_paths"]:
        print(f"    wrote {target}")

    if args.metadata:
        parsed = parse_metadata(result["metadata"])
        print(f"    metadata regkey={parsed['regkey']} ({parsed['size']}B)")
        for index, fields in enumerate(parsed["records"], start=1):
            print(f"      record {index}:")
            for field in fields:
                print(f"        {_format_metadata_field(field)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
